query:
mutation CreateCreatorCode($input: DiscountCodeBasicInput!) {
  discountCodeBasicCreate(basicCodeDiscount: $input) {
    codeDiscountNode {
      id
      codeDiscount {
        ... on DiscountCodeBasic {
          title
          codes(first: 10) { nodes { code } }
          startsAt
          endsAt
        }
      }
    }
    userErrors { field message code }
  }
}
